// Particles
const pc = document.getElementById('particles');
for(let i=0;i<30;i++){
const p=document.createElement('div');
p.className='particle';
const s=Math.random()*4+2;
p.style.width=s+'px';
p.style.height=s+'px';
p.style.left=Math.random()*100+'%';
p.style.animationDuration=Math.random()*10+10+'s';
p.style.animationDelay=Math.random()*5+'s';
p.style.opacity=Math.random()*.5+.2;
const colors=['rgba(108,92,231,.5)','rgba(0,206,201,.4)','rgba(253,121,168,.3)'];
p.style.background=colors[Math.floor(Math.random()*colors.length)];
pc.appendChild(p);
}

// Navbar scroll
window.addEventListener('scroll',()=>{
const n=document.getElementById('navbar');
if(window.scrollY>50)n.classList.add('scrolled');
else n.classList.remove('scrolled');
});

// Reveal on scroll
const obs=new IntersectionObserver((e)=>{
e.forEach(en=>{if(en.isIntersecting)en.target.classList.add('active')});
},{threshold:0.15});
document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));

// Scroll to section
function scrollToSection(id){
document.getElementById(id).scrollIntoView({behavior:'smooth'});
}

// Mobile menu
function toggleMenu(){
const nl=document.getElementById('navLinks');
if(nl.style.display==='flex')nl.style.display='';
else nl.style.display='flex';
nl.style.flexDirection='column';
nl.style.position='absolute';
nl.style.top='100%';
nl.style.right='0';
nl.style.left='0';
nl.style.background='rgba(10,10,26,.98)';
nl.style.padding='2rem 5%';
nl.style.gap='1.5rem';
}

// Smooth scroll for links
document.querySelectorAll('a[href^="#"]').forEach(a=>{
a.addEventListener('click',function(e){
const h=this.getAttribute('href');
if(h.length>1){
e.preventDefault();
document.querySelector(h).scrollIntoView({behavior:'smooth'});
const nl=document.getElementById('navLinks');
if(window.innerWidth<=768)nl.style.display='';
}
});
});
</script>
